INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66099682', 66099682, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Penyusunan Analisis dan Kelengkapan Data  Kesehatan Seksual dan Reproduksi serta Kekerasan terhadap  Perempuan dan Anak Perempuan Kegiatan Program Kerjasama Pemerintah RI dan UNFPA Siklus 11 (2026-2030)  TA 2026', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 82500000, 'February 2026', 'Lainnya', 1, 1, '1 Paket', 'Ruang lingkup pekerjaan Jasa Konsultan Penyusunan Analisis dan Kelengkapan Data KSR serta KtPAP adalah sebagai berikut: 1. Review dan kompilasi data KSR serta KtPAP a. Mengumpulkan, menelaah kelengkapan, serta memetakan sumber dan penyedia data KSR dan KtPAP; b. Mengidentifikasi permasalahan/tantangan yang dihadapi dalam pengumpulan, kelengkapan dan kualitas, dan kelengkapan data KSR serta KtPAP; dan c. Mengkompilasi data indikator kunci KSR dan KtPAP untuk dapat dimanfaatkan lebih lanjut. 2. Analisis data KSR serta KtPAP a. Mengikuti perkembangan isu-isu strategis KSR serta KtPAP; dan b. Mendukung penyusunan analisis data KSR dan KtPAP yang dibutuhkan dalam kegiatan penyusunan dokumen kerangka kebijakan, kajian, serta instrumen teknis dan advokasi. 3. Dukungan teknis koordinasi dan kolaborasi pemangku kepentingan a. Mendukung pelaksanaan pertemuan koordinasi/konsultasi lintas lembaga terkait kegiatan KSR dan KtPAP (misalnya rapat teknis, high level meeting, dan/atau forum pembahasan lainnya sesuai kebutuhan), termasuk menyiapkan analisis data/bahan paparan/brief note yang diperlukan, serta ringkasan hasil pembahasan; b. Memberikan masukan substantif untuk KSR serta KtPAP; dan c. Mengkonsolidasi hasil koordinasi dalam laporan kegiatan. 4. Penyusunan Laporan dan Transfer Knowledge a. Mendokumentasikan secara sistematis proses pelaksanaan, capaian dan hasil kegiatan penyusunan analisis dan kelengkapan data KSR serta KtPAP; b. Menyusun laporan kemajuan berkala mengenai perkembangan pekerjaan, isu/kendala, dan tindak lanjut; c. Menyusun laporan akhir yang memuat rangkuman proses, capaian output, rekomendasi tindak lanjut analisis dan kelengkapan data KSR serta KtPAP; dan d. Melakukan transfer of knowledge (alih pengetahuan) atas hasil pekerjaan kepada pemilik pekerjaan untuk memastikan keberlanjutan hasil pekerjaan dan membangun kemandirian internal.', 'Persyaratan yang diperlukan sebagai penyedia Jasa Konsultan Penyusunan Analisis dan Kelengkapan Data KSR serta KtPAP adalah sebagai berikut: 1. S1 ilmu Demografi, Sosial, Statistik. Kebijakan Publik, Kesehatan Masyarakat, Perencanaan Pembangunan, atau bidang disiplin yang relevan; 2. Diutamakan memiliki pengalaman bekerja di bidang yang relevan, antara lain perencanaan pembangunan, kesehatan, kependudukan, pembangunan kesetaraan gender, atau pembangunan sosial di Indonesia; 3. Memiliki pengetahuan yang memadai tentang KSR dan KtPAP; 4. Memiliki pengalaman dalam menyusun kajian, dokumen kebijakan/perencanaan, evaluasi kebijakan/program, atau analisis data pembangunan; 5. Memiliki kemampuan komunikasi dan penulisan laporan yang baik (Bahasa Indonesia), kemampuan Bahasa Inggris menjadi nilai tambah; 6. Menguasai perangkat analisis data/perkantoran (misalnya Excel/SPSS/Stata/R) dan pengolahan data/indikator; 7. Memiliki kemampuan komunikasi yang baik; 8. Pengalaman dan kemampuan untuk bekerja sama dan afiliasi dengan mitra Pemerintah dan sistem PBB adalah sebuah keuntungan; 9. Mampu bekerja secara independen di bawah pengawasan minimal; 10. Proaktif, teliti, berintegritas, dan berorientasi pada hasil; 11. Mempunyai NPWP; dan 12. Bukan PNS atau anggota TNI/POLRI.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2534227);
