INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66099816', 66099816, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Lainnya Monitoring, Evaluation, and Learning (MEL) Officer  Kegiatan Program Kerja Sama Pemerintah RI dan UNFPA Siklus 11 (2026-2030) TA 2026', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 112750000, 'February 2026', 'Lainnya', 1, 1, '1 Paket', 'III. Ruang Lingkup Pekerjaan /Tugas dan Tanggung Jawab: Ruang lingkup/tugas dan tanggung jawab Jasa Lainnya Monitoring, Evaluation, and Learning (MEL) Officer Kegiatan Program Kerja Sama Pemerintah RI-UNFPA Siklus 11 (2026-2030) TA 2026, adalah sebagai berikut: 1. Mendukung Kementerian PPN/Bappenas dalam menjalankan tugasnya sebagai GCA di bawah koordinasi Deputi Bidang Pembangunan Manusia dan Kebudayaan dalam: a. Mendukung NPM dalam memfasilitasi pertemuan koordinasi Tim Teknis, Tim Pengarah, Kelompok Kerja tematik yang dibentuk sesuai kebutuhan, Tinjauan Akhir Tahun (Annual Review), kegiatan pemantauan bersama, dan kegiatan evaluasi tematik berkoordinasi dengan Tim PM&E UNFPA; b. Mendukung NPM dalam menyiapkan format pemantauan dan evaluasi, mengumpulkan data dan informasi, menyelenggarakan pertemuan koordinasi dengan MP/MS dan UNFPA sesuai kebutuhan, serta menyiapkan analisis awal dan bahan/materi yang diperlukan, berkoordinasi dengan Tim PM&E UNFPA; c. Mendukung NPM dalam mengkonsolidasikan dan menyusun laporan kemajuan pelaksanaan program kerja sama secara kuartalan, termasuk hasil reviu akhir siklus program, serta menyiapkan usulan rekomendasi pembentukan kelompok kerja tematik dan tindak lanjut yang relevan untuk disampaikan kepada Tim Teknis dan Tim Pengarah, berkoordinasi dengan Tim PM&E UNFPA sebagai bagian dari mekanisme pelaporan dan evaluasi program bersama; d. Mendukung penyusunan notulensi, presentasi, kerangka acuan kegiatan, serta bahan dan materi yang terkait kegiatan pemantauan dan evaluasi, termasuk pertemuan koordinasi Tim Teknis, Tim Pengarah, dan kelompok kerja tematik, untuk selanjutnya didistribusikan secara tepat waktu kepada MP/MS, pemangku kepentingan terkait, dan UNFPA; e. Melakukan koordinasi aktif dengan MP/MS untuk memantau perkembangan pelaksanaan kegiatan, mengidentifikasi kendala, serta memberikan pengingat (reminder) berkala, dan memastikan kelengkapan dan kesesuaian format paparan MP/MS sebelum pertemuan koordinasi dilakukan; dan f. Mendukung pengelolaan pengetahuan program kerja sama melalui Portal Knowledge Hub dengan memastikan setiap produk telah mendapatkan review dari penanggung jawab program di Kementerian PPN/Bappenas dan UNFPA sebelum publikasi, memberikan pengingat kuartalan kepada MP/MS untuk mengunggah produk kegiatan, berkoordinasi dengan Pusat Sistem, Data dan Informasi Perencanaan Pembangunan (Pusdatinrenbang) Kementerian PPN/Bappenas dan programmer dalam pemeliharaan dan pemutakhiran aplikasi, serta memastikan konsistensi metadata sesuai regulasi Pemerintah RI yang berlaku guna mendukung institutional learning dan akuntabilitas program. 2. Mendukung Kementerian PPN/Bappenas dalam menjalankan tugasnya sebagai MP di bawah koordinasi Direktur Keluarga, Pengasuhan, Perempuan, dan Anak dalam: a. Mendukung NPM dalam memantau perkembangan pelaksanaan kegiatan sesuai AWP dan rencana kerja kuartalan Kementerian PPN/Bappenas; b. Mendukung pelaksana program pada unit terkait di Kementerian PPN/Bappenas dalam menyusun WPR secara kuartalan; c. Mendukung penyusunan bahan laporan perkembangan pelaksanaan program kerja sama sesuai kebutuhan Kementerian PPN/Bappenas; d. Berkontribusi dan mendukung pelaksanaan kegiatan Kementerian PPN/Bappenas sebagai MP sesuai rencana kerja yang telah disusun; dan e. Mendukung pelaksana program pada unit terkait di Kementerian PPN/Bappenas dalam mengkurasi, mendokumentasikan dan mengunggah produk pengetahuan yang dihasilkan melalui platform manajemen pengetahuan (Portal Knowledge Hub) secara reguler.', 'Persyaratan yang diperlukan sebagai penyedia Jasa Lainnya Monitoring, Evaluation, and Learning (MEL) Officer Kegiatan Program Kerja Sama Pemerintah RI-UNFPA Siklus 11 (2026-2030) TA 2026, adalah sebagai berikut: 1. Sarjana (S1) bidang Kesehatan, Demografi, Ilmu Kependudukan, Manajemen, Sosial, atau bidang lainnya yang relevan; 2. Pengalaman kerja minimal 1 tahun (gelar Master) atau 5 tahun (gelar Sarjana) di bidang perencanaan/manajemen/pemantauan/evaluasi suatu proyek di pemerintahan; 3. Memahami isu-isu bidang kependudukan, kesehatan reproduksi dan seksual, pemuda dan program gender di Indonesia 4. Mampu mengolah dan menganalisis data-data statistik; 5. Menguasai analisis dan penyajian infografis serta mengelola platform media sosial; 6. Menguasai manajemen pengelolaan produk pengetahuan (knowledge products), termasuk kurasi, peninjauan, dokumentasi, dan publikasi melalui platform manajemen pengetahuan; dan 7. Memiliki motivasi kerja dan kemauan belajar yang tinggi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2534579);
