INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66099705', 66099705, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Penyusunan Laporan Kegiatan  Peningkatan Kelengkapan dan Pemanfaatan Data Statistik Hayati Kegiatan Program Kerja Sama Pemerintah RI dan UNFPA Siklus 11 (2026-2030) TA 2026', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 85300000, 'February 2026', 'Lainnya', 1, 1, '1 Paket', 'Ruang lingkup pekerjaan Jasa Konsultan Penyusunan Laporan Kegiatan Peningkatan Kelengkapan dan Pemanfaatan Data Statistik Hayati meliputi: 1. Review kelengkapan Statistik Hayati a. Mengumpulkan, menelaah, mengkompilasi dokumen terkait implementasi Statistik Hayati di Indonesia (dokumen kebijakan, laporan, evaluasi, data dan indikator, hasil kajian, dan lainnya); dan b. Memetakan ketersediaan data eksisting dan penanggung jawab (penyedia) data Statistik Hayati (kelahiran, kematian, perkawinan, dan perceraian). 2. Analisis kesenjangan dan isu strategis Statistik Hayati a. Menelaah kesenjangan data Statistik Hayati; b. Mengidentifikasi permasalahan/tantangan yang dihadapi dalam pengumpulan, kelengkapan dan kualitas, dan pemanfaatan lebih lanjut Statistik Hayati untuk kebijakan dan program pembangunan dan kependudukan; dan c. Menyusun rekomendasi penguatan kelengkapan dan pemanfaatan data Statistik Hayati. 3. Dukungan teknis koordinasi dan kolaborasi pemangku kepentingan a. Mengikuti perkembangan isu-isu strategis implementasi Statistik Hayati. b. Menjaga hubungan komunikasi yang baik dengan pihak terkait seperti lembaga pemerintah, instansi terkait, pemerintah daerah, dan/atau akademisi; c. Mendukung pelaksanaan pertemuan koordinasi/konsultasi lintas lembaga (misalnya rapat teknis, high level meeting, dan/atau forum pembahasan lainnya sesuai kebutuhan), termasuk menyiapkan bahan paparan dan ringkasan hasil pembahasan; d. Memberikan masukan substantif untuk penguatan Statistik Hayati; dan e. Mengkonsolidasi hasil koordinasi dalam laporan kegiatan peningkatan kelengkapan dan pemanfaatan data Statistik Hayati. 4. Penyusunan Laporan dan Transfer Knowledge a. Mendokumentasikan secara sistematis proses pelaksanaan, capaian dan hasil kegiatan peningkatan kelengkapan dan pemanfaatan data Statistik Hayati; b. Menyusun laporan kemajuan berkala mengenai perkembangan pekerjaan, isu/kendala, dan tindak lanjut; c. Menyusun laporan akhir yang memuat rangkuman proses, capaian output, rekomendasi tindak lanjut peningkatan kelengkapan dan pemanfaatan data Statistik Hayati; dan d. Melakukan transfer of knowledge (alih pengetahuan) atas hasil pekerjaan kepada pemilik pekerjaan untuk memastikan keberlanjutan hasil pekerjaan dan membangun kemandirian internal.', 'Jasa Konsultan Penyusunan Laporan Kegiatan Peningkatan Kelengkapan dan Pemanfaatan Data Statistik Hayati dibutuhkan memiliki kualifikasi sebagai berikut: 1. S1 ilmu Demografi/Kependudukan dan/atau Perencanaan Pembangunan dan/atau Sosial dan/atau Kebijakan Publik dan /atau bidang disiplin lain yang terkait; 2. Memiliki pengalaman dalam penyusunan dokumen kebijakan/perencanaan, evaluasi kebijakan/program, atau analisis pembangunan (diutamakan bidang kependudukan); 3. Memiliki pengetahuan yang memadai mengenai Statistik Hayati; 4. Memiliki pengalaman koordinasi lintas K/L dan/atau bekerja sama dengan mitra pembangunan menjadi nilai tambah; 5. Memiliki kemampuan komunikasi dan penulisan laporan yang baik (Bahasa Indonesia); kemampuan Bahasa Inggris menjadi nilai tambah; 6. Memiliki kemampuan mengelola pekerjaan berbasis jadwal dan menyusun output sesuai tenggat waktu; 7. Menguasai perangkat analisis data/perkantoran (misalnya Excel/SPSS/Stata/R) dan pengolahan data/indikator; 8. Proaktif, teliti, berintegritas, dan berorientasi pada hasil; 9. Mampu bekerja mandiri dan kolaboratif, serta bekerja di bawah tekanan waktu; dan 10. Bukan PNS atau anggota TNI/POLRI.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2534779);
