INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66099776', 66099776, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Penyempurnaan Dokumen  Desain Besar Pembangunan Kependudukan (DBPK) melalui  Review Implementasi Grand Design Pembangunan Kependudukan (GDPK) Kegiatan Program Kerja Sama Pemerintah RI-UNFPA Siklus 11 (2026-2030) TA 2026', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 99960000, 'February 2026', 'Lainnya', 1, 1, '1 Paket', 'III. Ruang Lingkup Pekerjaan Ruang lingkup pekerjaan Jasa Konsultan Penyempurnaan Dokumen Desain Besar Pembangunan Kependudukan (DBPK) melalui Review Implementasi Grand Design Pembangunan Kependudukan (GDPK) meliputi: 1. Review Implementasi GDPK Sebelumnya a. Mengumpulkan, menelaah, dan mengkompilasi dokumen terkait implementasi GDPK sebelumnya (dokumen kebijakan, laporan, evaluasi, indikator, hasil kajian, dan data pendukung); b. Menyusun kerangka/metodologi review (ruang lingkup, indikator review, sumber data, serta rencana kerja); c. Melakukan analisis capaian, hambatan, kesenjangan kebijakan/indikator, dan faktor pendukung/penghambat pelaksanaan, termasuk aspek kelembagaan, koordinasi, data, dan pembiayaan; dan d. Menyusun rekomendasi penyempurnaan yang operasional sebagai masukan substansi Lampiran RPerpres DBPK. 2. Penyusunan dan Penyempurnaan Lampiran RPerpres DBPK a. Menyusun Lampiran RPerpres DBPK berdasarkan hasil reviu implementasi GDPK sebelumnya serta kebutuhan kebijakan terkini; b. Memastikan konsistensi internal Lampiran (isu–arah kebijakan–strategi–indikator) dan keterpaduan lintas sektor; c. Menyempurnakan Lampiran melalui proses iterasi berdasarkan masukan internal dan eksternal; dan d. Menyusun ringkasan eksekutif/brief substansi yang memudahkan proses pembahasan dan pengambilan keputusan. 3. Koordinasi Teknis dan Kolaborasi Pemangku Kepentingan a. Menjaga hubungan komunikasi yang baik dengan pihak terkait seperti lembaga pemerintah, instansi terkait, dan masyarakat; b. Mendukung pelaksanaan konsultasi teknis/rapat lintas K/L (misalnya rapat teknis, high level meeting, dan/atau forum pembahasan lainnya sesuai kebutuhan), termasuk menyiapkan bahan paparan, dan ringkasan hasil pembahasan; dan c. Mengkompilasi masukan pemangku kepentingan dan mengintegrasikannya ke dalam penyempurnaan Lampiran RPerpres DBPK. 4. Dukungan Teknis Substansi untuk Proses Pengesahan RPerpres DBPK a. Menyiapkan dokumen dukungan substansi yang dibutuhkan pada tahapan proses pengesahan (misalnya matriks respons atas masukan, penjelasan substansi, dan bahan klarifikasi); dan b. Mendukung konsolidasi substansi dokumen pada tahapan finalisasi sesuai arahan Kementerian PPN/Bappenas.', 'Persyaratan penyedia Jasa Konsultan Penyempurnaan Dokumen Desain Besar Pembangunan Kependudukan (DBPK) melalui Review Implementasi Grand Design Pembangunan Kependudukan (GDPK) adalah sebagai berikut: 1. Minimal Magister (S2) bidang Demografi, Ilmu Sosial, Kebijakan Publik, Perencanaan Pembangunan, Ekonomi, Kesehatan Masyarakat, Statistik, atau bidang terkait yang relevan; 2. Memiliki pengalaman minimal 1 (satu) tahun dalam penyusunan dokumen kebijakan/perencanaan, evaluasi kebijakan/program, atau analisis pembangunan (diutamakan bidang kependudukan); 3. Memiliki pengalaman koordinasi lintas K/L dan/atau bekerja sama dengan mitra pembangunan menjadi nilai tambah; 4. Memiliki kemampuan analisis kebijakan, penyusunan naskah kebijakan, dan penguatan indikator/target; 5. Memiliki kemampuan komunikasi dan penulisan laporan yang baik (Bahasa Indonesia); kemampuan Bahasa Inggris menjadi nilai tambah; 6. Memiliki kemampuan mengelola pekerjaan berbasis jadwal dan menyusun output sesuai tenggat waktu; 7. Menguasai perangkat analisis data/perkantoran (misalnya Excel/SPSS/Stata/R) dan pengolahan data/indikator; 8. Proaktif, teliti, berintegritas, dan berorientasi pada hasil; 9. Mampu bekerja mandiri dan kolaboratif, serta bekerja di bawah tekanan waktu; dan 10. Bukan PNS atau anggota TNI/POLRI.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2534925);
