INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66099769', 66099769, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Penyusunan Studi Pembiayaan Kesehatan Bagi Korban Kekerasan terhadap Perempuan dan Anak Perempuan (KtPAP) untuk Mendukung Kerangka Nasional Pencegahan dan Penanganan KtPAP serta Praktik Berbahaya Kegiatan Program Kerja Sama Pemerintah RI-UNFPA Siklus 11 (2026-2030) TA 2026', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 75000000, 'March 2026', 'Lainnya', 1, 1, '1 Paket', 'Ruang lingkup pekerjaan Jasa Konsultan Penyusunan Studi Pembiayaan Kesehatan Bagi Korban KtPAP untuk Mendukung Kerangka Nasional Pencegahan dan Penanganan KtPAP serta Praktik Berbahaya, antara lain: 1. Pengumpulan dan Analisis Data a. Review kebijakan, peraturan, dan standar nasional terkait pembiayaan layanan kesehatan dan layanan bantuan hukum bagi korban KtPAP dan praktik berbahaya; b. Pemetaan skema pembiayaan yang tersedia (APBN, APBD, JKN/BPJS, mekanisme lintas sektor, layanan UPTD PPA, P2TP2A, organisasi sosial kemasyarakatan/CSO); c. Pengumpulan data biaya dan alur layanan dari berbagai unit layanan (fasilitas kesehatan, UPTD PPA, penyedia layanan berbasis masyarakat); dan d. Identifikasi kebutuhan biaya riil (direct and indirect cost) untuk layanan kesehatan.. 2. Penyusunan Analisis Biaya a. Melakukan costing analysis untuk menentukan paket biaya layanan berdasarkan standar layanan minimum; b. Melakukan analisis kesenjangan antara kebutuhan biaya dan sumber pendanaan yang tersedia; dan c. Menganalisis opsi pembiayaan yang dapat digunakan untuk menjamin keberlanjutan layanan. 3. Konsultasi Pemangku Kepentingan a. Melakukan wawancara mendalam, FGD dan konsultasi teknis dengan Kementerian PPN/Bappenas, Kementerian PPPA, Kemenkes, pemda, penyedia layanan, dan mitra terkait; dan b. Memperoleh masukan teknis dari pemangku kepentingan untuk penyempurnaan analisis biaya dan rekomendasi. 4. Penyusunan Dokumen Studi a. Menyusun laporan studi, dan b. Menyusun policy brief atau ringkasan eksekutif. 5. Diseminasi Hasil Studi a. Menyampaikan hasil studi dan rekomendasi kebijakan kepada pemangku kepentingan terkait di tingkat pusat dan daerah; dan b. Melaksanakan transfer of knowledge (alih pengetahuan) atas hasil pekerjaan kepada pemilik pekerjaan untuk memastikan keberlanjutan hasil pekerjaan dan membangun kemandirian internal.', 'Persyaratan penyedia Jasa Konsultan Penyusunan Studi Pembiayaan Kesehatan Bagi Korban KtPAP untuk Mendukung Kerangka Nasional Pencegahan dan Penanganan KtPAP serta Praktik Berbahaya adalah sebagai berikut: 1. Pendidikan minimal magister (S2) di bidang kesehatan masyarakat, kebijakan publik, studi gender, ekonomi, statistik, ekonomi kesehatan, atau bidang terkait; 2. Memiliki pengalaman dalam analisis pembiayaan (costing), kajian pembiayaan publik, analisis anggaran, lebih disukai jika terkait analisis biaya layanan kesehatan atau pembiayaan JKN/BPJS, 3. Memiliki pengalaman minimal 7 (tujuh) tahun dalam penelitian, analisis kebijakan, atau pengembangan program terkait kesehatan, gender, atau perlindungan perempuan dan anak; 4. Memahami isu KtPAP, perlindungan perempuan dan anak, layanan komprehensif, serta norma dan standar internasional terkait KtPAP; 5. Memiliki pengetahuan tentang standar layanan (SOP) penanganan korban kekerasan, termasuk clinical management of rape dan layanan kesehatan reproduksi; 6. Memiliki kemampuan analitis yang kuat dan pengalaman menyusun laporan kebijakan; 7. Memiliki pengalaman bekerja dengan lembaga pemerintah, organisasi internasional, atau penyedia layanan berbasis masyarakat menjadi nilai tambah; 8. Memiliki kemampuan komunikasi, fasilitasi, dan konsultasi pemangku kepentingan; dan 9. Bukan PNS atau anggota TNI/Polri.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2537057);
