INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66099759', 66099759, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Penyusunan Pedoman Perencanaan dan Penganggaran  untuk Implementasi Kerangka Nasional Pencegahan dan Penanganan  Kekerasan Terhadap Perempuan dan Anak Perempuan (KtPAP) serta Praktik Berbahaya Kegiatan Program Kerja Sama Pemerintah RI-UNFPA Siklus 11 (2026-2030) TA 2026', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 70000000, 'March 2026', 'Lainnya', 1, 1, '1 Paket', 'Ruang lingkup pekerjaan Jasa Konsultan Penyusunan Pedoman Perencanaan dan Penganggaran untuk Implementasi Kerangka Nasional Pencegahan dan Penanganan Kekerasan terhadap Perempuan dan Anak (KtPAP) serta Praktik Berbahaya di Tingkat Daerah, antara lain: 1. Melakukan kajian terhadap regulasi perencanaan dan pengelolaan keuangan daerah yang relevan dengan upaya pencegahan dan penanganan KtPAP dan praktik berbahaya; 2. Mengidentifikasi praktik baik daerah dalam penyelenggaraan perencanaan dan penganggaran untuk penanganan KtPAP dan praktik berbahaya; 3. Menyusun kerangka operasional perencanaan dan penganggaran pencegahan dan penanganan KtPAP dan praktik berbahaya di tingkat daerah yang meliputi: - Panduan integrasi isu pencegahan dan penanganan KtPAP dan praktik berbahaya ke dalam dokumen perencanaan dan penganggaran daerah, mencakup RPJMD, Renstra-PD, RKPD, Renja-PD, hingga RKA; - Perumusan indikator kerja daerah terkait pencegahan dan penanganan KtPAP dan praktik berbahaya; dan - Strategi optimalisasi berbagai sumber pendanaan di daerah untuk keberlanjutan unit layanan pencegahan dan penanganan KtPAP dan praktik berbahaya; 4. Mengintegrasikan masukan dari FGD, workshop, kunjungan lapangan, dan pertemuan koordinasi dalam penyusunan dan penyempurnaan draf pedoman; dan 5. Menyusun dan melakukan finalisasi dokumen Pedoman Perencanaan dan Penganggaran Pencegahan dan Penanganan Kekerasan terhadap Perempuan dan Anak (KtPAP) serta Praktik Berbahaya di Tingkat Daerah.', 'Persyaratan penyedia Jasa Konsultan Penyusunan Pedoman Perencanaan dan Penganggaran untuk Implementasi Kerangka Nasional Pencegahan dan Penanganan Kekerasan terhadap Perempuan dan Anak (KtPAP) serta Praktik Berbahaya di Tingkat Daerah adalah sebagai berikut: 1. Pendidikan minimal magister (S2) di bidang kebijakan publik, studi gender, hukum, administrasi negara, sosial, atau bidang lain yang relevan; 2. Memiliki pengalaman kerja minimal 8-10 tahun dalam penyusunan kebijakan nasional, strategi, framework, kajian kelembagaan, atau tata kelola pemerintahan, khususnya di bidang kesetaraan gender, perlindungan perempuan dan anak, dan/atau pembangunan sosial; 3. Memiliki pengalaman memimpin atau terlibat aktif dalam penyusunan dokumen kebijakan nasional dan/atau lintas sektor, termasuk perumusan rekomendasi kebijakan yang bersifat strategis dan aplikatif; 4. Memahami pendekatan pencegahan dan penanganan KtPAP dan praktik berbahaya, termasuk pencegahan primer, sekunder, dan tersier, serta sistem layanan perlindungan yang terkait; 5. Memahami sistem pemerintahan pusat dan daerah, termasuk mekanisme perencanaan dan penganggaran program pembangunan, serta mekanisme koordinasi dan hubungan kerja lintas sektor; 6. Berpengalaman dalam memfasilitasi diskusi kelompok terarah (FGD), workshop, konsinyering, dan proses konsultasi kebijakan dengan berbagai pemangku kepentingan; 7. Memiliki pengalaman dalam penyusunan panduan/pedoman/petunjuk teknis implementasi program, lebih disukai jika terkait perencanaan dan penganggaran; dan 8. Bukan PNS atau anggota TNI/Polri.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2537351);
