INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66064521', 66064521, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'KONSULTAN JUNIOR PENYUSUNAN REKOMENDASI KEBIJAKAN DAN PENGENDALIAN PELAKSANAAN MANAJEMEN TALENTA NASIONAL (MTN)', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 99996000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '12 Bulan', '1. Melakukan penilaian dan pengendalian pelaksanaan program dan kegiatan Manajemen Talenta Nasional Bidang Seni Budaya, Olahraga, serta Riset dan Inovasi untuk memastikan kesesuaian dengan perencanaan, standar kualitas, serta ketentuan peraturan perundang-undangan. 2. Menyediakan data terolah, analisis kebijakan, serta rekomendasi perbaikan berbasis eviden sebagai bahan pengambilan keputusan dan penyempurnaan pelaksanaan Manajemen Talenta Nasional. 3. Menjamin tersusunnya laporan kinerja berkala dan tahunan yang analitis, akurat, dan dapat dipertanggungjawabkan, termasuk penjabaran temuan, implikasi kebijakan, serta usulan tindak lanjut pengendalian pelaksanaan MTN.', 'a. Bukan PNS atau anggota TNI/Polri; b. Pendidikan S1/S2 dari dalam atau luar negeri dengan jurusan Kebijakan Publik, Planologi, Ilmu Statistik, Ilmu Manajemen, Ilmu Budaya, Ilmu Olahraga, atau jurusan lain yang relevan c. Memiliki pengalaman minimal 2 (dua) tahun dalam penelitian dan penyusunan kebijakan yang berkaitan dengan manajemen talenta; d. IPK minimal 3,25 (dari skala 4,00); e. Tertarik dengan isu-isu kebijakan terkait kegiatan ini; f. Memiliki kemampuan dalam penulisan ilmiah dan mempunyai karya tulis ilmiah; g. Bersedia bekerja mulai bulan Januari 2026 – Desember 2026; dan h. Mampu bekerja dengan baik, disiplin, dan sungguh-sungguh serta mempunyai komitmen dan motivasi untuk bekerja sama dalam tim; i. Sudah memiliki akun LPSE dan/atau memiliki NIB Perorangan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2537696);
