INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66100930', 66100930, 'analyze_legacy', 'Kab. Kepulauan Yapen', 'kabkota', 'Dinas Perikanan', 'Perencanaan, dan Pengembangan Pemanfaatan Air untuk Pembudidayaan Ikan di Darat', 'Jasa Lainnya', 'Pengadaan Langsung', 'Papua, Kepulauan Yapen (Kab.)', 300000000, 'March 2026', 'APBD', 1, 1, '1 Paket', 'Belanja Kursus Singkat/Pelatihan; Beban Kursus Singkat/Pelatihan;', 'PEMBUATAN DOKUMEN RZWP3K; PEMBUATAN DOKUMEN RZWP3K;', 300000000, 'high', 'Terdapat indikasi kuat ketidaksesuaian antara uraian belanja kursus/pelatihan dengan spesifikasi pembuatan dokumen RZWP3K. Ketidakkonsistenan jenis output dan akun belanja ini menunjukkan item berpotensi tidak tepat klasifikasi atau tidak tepat peruntukan, sehingga seluruh nilai patut dicermati sebagai potensi pemborosan.', NULL, NULL, 3, 1, 1, 1, 1, 2538312);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66101066', 66101066, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'KANTOR PUSAT DIREKTORAT JENDERAL PERKERETAAPIAN', 'Pengelolaan/Managed Service Aplikasi Portal Layanan Direktorat Jenderal Perkeretaapian', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 1400000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Maksud dari kegiatan Pengelolaan/ Managed Service Aplikasi Portal Layanan Ditjen Perkeretaapian adalah memudahkan dalam mengakses, mengelola, memperoleh/ mengintegrasikan data/informasi, serta memperbaiki gangguan/ permasalahan yang ada pada semua aplikasi yang terintegrasi menjadi layanan pada portal lingkungan Direktorat Jenderal Perkeretaapian dalam satu pengelolaan yang komprehensif. Managed service aplikasi ini diperuntukan dalam pengelolaan aplikasi secara Software Development Life Cycle (SDLC) untuk mendukung pengelolaan infrastruktur.', 'Secara garis besar ruang lingkup dalam kegiatan Sewa Managed Service SDLC Aplikasi dan Infrastruktur portal layanan Ditjen Perkeretaapian ini dapat dijelaskan sebagai berikut: 1. Perencanaan dan Analisis Kebutuhan a. Melakukan analisis proses bisnis dan fungsionalitas sistem berupa modul layanan yang terintegrasi dengan portal layanan dan data Direktorat Jenderal Perkeretaapian. b. Melakukan identifikasi terhadap kebutuhan pengguna aplikasi. 2. Perancangan Sistem (System Design) a. Membuat perancangan arsitektur aplikasi yang saling terintegrasi antar modul layanan b. Membuat Desain antarmuka pengguna (UI/UX) yang user friendly dari semua jenis perangkat yang mengakses baik desktop maupun mobile. c. Penyusunan dokumen desain teknis untuk pelaksanaan pengembangan dan pengelolaan aplikasi. d. Mempersiapkan Infrastruktur server yang dibutuhkan berbasis container untuk mendukung arsitektur microservices. 3. Pengembangan Aplikasi (Development) a. Melakukan Implementasi terhadap rencana pengembangan aplikasi yang sesuai spesifikasi desain. b. Mengakomodir proses Integrasi modul layanan pada PLD Ditjen Perkeretaapian. c. Melakukan perbaikan dan pengelolaan versi aplikasi (version control). d. Melakukan pengelolaan dan pengembangan aplikasi yang mengakomodir faktor keamanan aplikasi menggunakan konsep DevSecOps yang terdiri dari pengembangan (development), keamanan (security), dan operasi (operations). e. Menyediakan fitur pengaduan/layanan pengguna yang dihubungkan dengan penganggung jawab masing-masing layanan. f. Menyediakan aplikasi mobile dengan menggunakan branding PLD DJKA yang mengakomodir : 1. Informasi layanan Masyarakat pada bidang perkeretaapian yang terintegrasi dengan penyelenggara perkeretaapian; 2. Fitur pengecekan proses layanan; 3. Pelaporan Masyarakat serta monitoring tindak lanjut; 4. Dashboard Monitoring persetujuan terpusat. g. Peningkatan fitur pada database perencanaan teknis (monitoring dokumen persetujuan lingkungan hidup); h. Peningkatan fitur pada peta perkeretaapian berupa penambahan data spasial rencana pengembangan jaringan kereta api. 4. Pemeliharaan dan Dukungan Teknis (Maintenance & Support) a. Pemeliharaan dan perawatan sistem aplikasi meliputi modul-modul yang terintegrasi dengan PLD Ditjen Perkeretaapian. b. Perbaikan bug dan error pada aplikasi utama dan intgerasi dengan modul layanan. c. Pembaruan dan patch sistem secara berkala untuk meningkatkan kehandalan dan keamanan aplikasi. d. Dukungan layanan pengguna (helpdesk) terdiri atas dukungan operasi layanan layer 1 on-site dan layer 2 on-call 24x7. e. Waktu kerja Weekdays On-site (Senin - Kamis 08.00 - 16.30 dan Jumat 08.00 - 17.00) 5. Evaluasi, Perbaikan Berkelanjutan dan Dokumentasi a. Review kinerja PLD Ditjen Perkeretaapian beserta modul yang terintegrasi. b. Penyempurnaan sistem PLD Ditjen Perkeretaapian berdasarkan feedback pengguna. c. Menyusun laporan/dokumentasi teknis berkala atas segala permasalahan dan penyelesaian permasalahan yang ada dalam kerangka acuan managed service operasional, termasuk penyediaan sarana/ fitur tindak lanjut menggunakan ticketing sistem pelaporan dan penyelesaian.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2538313);
