INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66099738', 66099738, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Penyusunan Kerangka Nasional Pencegahan dan Penanganan Kekerasan terhadap Perempuan dan Anak Perempuan (KtPAP) serta Praktik Berbahaya Kegiatan Program Kerja Sama Pemerintah RI-UNFPA Siklus 11 (2026-2030) TA 2026', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 70000000, 'March 2026', 'Lainnya', 1, 1, '1 Paket', 'III. Lingkup Pekerjaan Ruang lingkup pekerjaan Jasa Konsultan Penyusunan Kerangka Nasional Pencegahan dan Penanganan Kekerasan terhadap Perempuan dan Anak Perempuan (KtPAP) serta Praktik Berbahaya, antara lain: 1. Melakukan kajian kebijakan dan regulasi nasional serta praktik internasional terkait pencegahan dan penanganan KtPAP dan praktik berbahaya. 2. Menyusun kerangka konseptual dan operasional Kerangka Nasional Pencegahan dan Penanganan KtPAP serta Praktik Berbahaya, meliputi: a. Prinsip, tujuan, dan pendekatan pencegahan dan respon KtPAP; b. Strategi pencegahan primer, sekunder, dan tersier; c. Mekanisme respons, perlindungan, dan pemulihan korban; d. Tata kelola, koordinasi lintas sektor, dan peran pusat–daerah; dan e. Kerangka pemantauan dan evaluasi. 3. Mengintegrasikan masukan dari focus group discussions (FGD), workshop, kunjungan lapangan, dan pertemuan koordinasi. 4. Menyusun dan memfinalisasi dokumen Kerangka Nasional Pencegahan dan Penanganan KtPAP serta Praktik Berbahaya. 5. Melaksanakan transfer of knowledge (Alih Pengetahuan) atas hasil pekerjaan kepada pemilik pekerjaan untuk memastikan keberlanjutan hasil pekerjaan dan membangun kemandirian internal.', 'Persyaratan jasa konsultan Penyusunan Kerangka Nasional Pencegahan dan Penanganan Kekerasan terhadap Perempuan dan Anak Perempuan (KtPAP) serta Praktik Berbahaya adalah sebagai berikut: 1. Pendidikan minimal magister (S2) di bidang kebijakan publik, studi gender, hukum, administrasi negara, sosial, atau bidang lain yang relevan; 2. Memiliki pengalaman kerja minimal 8-10 tahun dalam penyusunan kebijakan nasional, strategi, framework, kajian kelembagaan, atau tata kelola pemerintahan, khususnya di bidang kesetaraan gender, perlindungan perempuan dan anak, dan/atau pembangunan sosial; 3. Memiliki pengalaman memimpin atau terlibat aktif dalam penyusunan dokumen kebijakan nasional dan/atau lintas sektor, termasuk perumusan rekomendasi kebijakan yang bersifat strategis dan aplikatif; 4. Memahami pendekatan pencegahan dan penanganan KtPAP dan praktik berbahaya, termasuk pencegahan primer, sekunder, dan tersier, serta sistem layanan perlindungan yang terkait; 5. Memahami sistem pemerintahan pusat dan daerah, termasuk mekanisme koordinasi antar K/L serta hubungan kerja lintas sektor; 6. Berpengalaman dalam memfasilitasi diskusi kelompok terarah (FGD), workshop, konsinyering, dan proses konsultasi kebijakan dengan berbagai pemangku kepentingan; 7. Memiliki pengalaman dalam penyusunan rekomendasi kebijakan kelembagaan, termasuk pembentukan atau penguatan tim/kelembagaan nasional; dan 8. Bukan PNS atau anggota TNI/Polri.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2538611);
