INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66064296', 66064296, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'BALAI BESAR VETERINER DENPASAR', 'Pengadaan bahan habis pakai pengujian dan bahan uji di laboratorium Patologi dalam rangka Penyidikan dan Pengujian Penyakit Hewan Melalui Sampel Pasif paket 1', 'Barang', 'Pengadaan Langsung', 'Bali, Denpasar (Kota)', 167500000, 'February 2026', 'Lainnya', 1, 0, '258', 'Pengadaan bahan habis pakai pengujian dan bahan uji di Laboratorium Patologi dalam rangka penyidikan dan pengujian penyakit hewan melalui sampel pasif Paket 1 meliputi objek glass sebanyak 54 box, Conjugate Rabies antinukleokapsid sebanyak 5 box, nitric acid sebanyak 1 botol, PBS tablet sebanyak 3 botol, toluene kemasan 4 liter sebanyak 7 botol, kertas saring sebanyak 12 box, sarung tangan ukuran L sebanyak 15 box dan ukuran M sebanyak 40 box, surgical mask sebanyak 32 box, tissue roll sebanyak 100 roll, lampu merkuri FAT Olympus sebanyak 1 buah, parafin @1 kg sebanyak 19 boks, alkohol 96% sebanyak 12 botol, kanebo sebanyak 2 buah, serta tissue box atau tissue dispenser tempel dinding sebanyak 5 buah.', 'Conjugate Rabies antinukleokapsid, spesifikasi lyophilised, adsorbed anti-rabies nucleocapsid conjugate, 4 qs ad 3 ml, merek BIO-RAD, nomor katalog 3572112. Objek glass berupa slide glass ukuran 26 × 76 mm frosted, isi 72 buah per boks, merek Sail Brand, nomor katalog 7105. Toluene kemasan 4 liter per botol, merek Smartlab, nomor katalog A 1075 4 Lt. Kertas saring diameter 150 mm, 100 circles, merek Whatman, nomor katalog 1441-150. Sarung tangan lateks tanpa bedak ukuran L, isi 1 boks 100 lembar, merek Sensi. Sarung tangan lateks tanpa bedak ukuran M, isi 1 boks 100 lembar, merek Sensi. Masker bedah tipe earloop 3 ply, isi 50 per boks, merek Onemed. Tissue roll 2 ply dengan 238 lembar, merek Nice. Lampu merkuri mikroskop tipe Ushio 100 W ultra-high pressure mercury lamp USH-1030L, merek Olympus, nomor katalog USH 1030 L. Parafin jenis Paraplast Tissue Embedding Medium, kemasan 1 kg per boks, merek Leica, nomor katalog 39601006. Nitric acid 65% for analysis EMSURE, kemasan 2,5 liter per botol, merek Merck, nomor katalog ME 1 00456 2500. Alkohol 95% kemasan 1 liter per botol, merek Onemed. Kanebo berbahan lembut dengan daya serap tinggi. PBS Tablet isi 50 tablet per botol, merek Sigma, nomor katalog P 4417-50 Tab. Box tissue berupa dispenser tissue tempel dinding, merek Subron.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2538703);
