INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66099826', 66099826, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Lainnya Finance and Administrative Assistant (FAA)  Kegiatan Program Kerja Sama Pemerintah RI dan UNFPA Siklus 11 (2026-2030) TA 2026', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 105990000, 'February 2026', 'Lainnya', 1, 1, '1 Paket', 'Ruang lingkup/tugas dan tanggung jawab Jasa Lainnya Finance and Administrative Assistant (FAA) Kegiatan Program Kerja Sama Pemerintah RI-UNFPA Siklus 11 (2026-2030) TA 2026, adalah sebagai berikut: 1. Mendukung Kementerian PPN/Bappenas dalam mengelola dana program/kegiatan yang telah dialokasikan dalam Annual Work Plan (AWP) Tahun 2025; 2. Membuat laporan keuangan secara rutin untuk dilaporkan kepada Koordinator Program (Eselon 2) melalui PJOK; 3. Berkoordinasi dengan Bendahara Kementerian PPN/Bappenas, PPK PPN V dan Bendahara Pembantu dalam pencairan dana maupun laporan keuangan; 4. Berkoordinasi dengan bagian keuangan Bappenas dalam menyiapkan laporan keuangan dan memastikan bahwa laporan tersebut sudah dikirimkan secara resmi dan tepat waktu (laporan rekonsiliasi dan pengesahan hibah); 5. Menyiapkan bukti penerimaan bank/kas dan bukti pengeluaran bank/kas; 6. Memeriksa/verifikasi laporan pertanggungjawaban uang muka; 7. Memeriksa keabsahan dan kebenaran dokumen-dokumen pembukuan yang diterima dan memastikan semua pengeluaran didukung dengan dokumen yang diperlukan, pembayaran tepat waktu, persetujuan telah dicatat dan invoice sudah dinomori sesuai urutan kedatangan; 8. Memonitor penggunaan uang muka termasuk didalamnya jangka waktu uang muka beredar; 9. Melakukan pencatatan semua transaksi keuangan sesuai dengan prosedur akuntansi; 10. Membuat laporan keuangan dan rekonsiliasi bank; 11. Memegang Kas Kecil yang terbatas dipergunakan untuk operasional kantor; 12. Mengarsipkan semua bukti/dokumen pembukuan secara rapi dan teratur; 13. Membantu menyiapkan dokumen yang dibutuhkan terkait revisi anggaran (realokasi dana ke UNFPA dan revisi DIPA ke Bappenas) berkoordinasi dengan Programme and Budget Management Associate (PBMA); 14. Memantau status keuangan program/kegiatan serta melaporkannya per bulan kepada Project Officer/PJOK; dan 15. Menyiapkan laporan keuangan dalam bentuk format Funding Certification Authorized Expenditure/FACE, dan memastikan FACE: ● diserahkan kepada UNFPA sesuai jadwal yang sudah ditentukan; akurasi perhitungan keuangan; ● sudah ditandatangani secara resmi oleh pejabat terkait (Program Koordinator, PJOK, dan Pemegang Uang Muka Kegiatan/PUMK); ● dan jumlah dana yang tertera di dalam FACE sesuai dengan alokasi di dalam Annual Work Plan (AWP).', 'Persyaratan yang diperlukan sebagai penyedia Jasa Lainnya Finance and Administrative Assistant (FAA) Kegiatan Program Kerja Sama Pemerintah RI-UNFPA Siklus 11 (2026-2030) TA 2026, adalah sebagai berikut: 1. Sarjana (S1) bidang Keuangan, Akuntansi, Manajemen Bisnis, Manajemen, atau bidang lainnya yang relevan; 2. Berpengalaman di bidang administrasi dan manajemen keuangan; 3. Berpengalaman bekerja dengan pemerintah atau LSM sangat diutamakan; 4. Pengalaman kerja minimal 5 tahun di bidang yang sejenis; dan 5. Memiliki motivasi kerja dan kemauan belajar yang tinggi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2539016);
